package pe.edu.utec.labreserve.service;
import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import pe.edu.utec.labreserve.config.UserPrincipal; import pe.edu.utec.labreserve.dto.request.CreateProductRequestDto; import pe.edu.utec.labreserve.dto.response.*; import pe.edu.utec.labreserve.entity.*; import pe.edu.utec.labreserve.exception.*; import pe.edu.utec.labreserve.repository.*; import java.math.BigDecimal;
@Service public class ProductService{private final ProductRepository products; private final StoreRepository stores; public ProductService(ProductRepository products,StoreRepository stores){this.products=products;this.stores=stores;}
 @Transactional public ProductResponseDto publish(Long storeId,CreateProductRequestDto r,UserPrincipal user){Store s=stores.findById(storeId).orElseThrow(()->new StoreNotFoundException("storeId: "+storeId)); boolean admin=user.getAuthorities().stream().anyMatch(a->a.getAuthority().equals(RoleConstants.ROLE_ADMIN)); if(!admin && !s.getOwnerId().equals(user.getId()))throw new ForbiddenStoreActionException("Usuario no es dueño del local"); if(!"OPEN".equals(s.getStatus()))throw new ProductNotAvailableException("Local no disponible"); if(products.existsByStoreIdAndName(storeId,r.name()))throw new ProductAlreadyExistsException("El nombre no puede repetirse dentro del mismo local"); String st=r.stock()>0?"AVAILABLE":"SOLD_OUT"; Product p=products.save(new Product(storeId,r.name(),r.price(),r.stock(),st)); return toResponse(p,s);}
 @Transactional(readOnly=true) public PagedResponseDto<PublicProductResponseDto> list(Long storeId,BigDecimal maxPrice,int page,int size){Page<Product> p=products.findAvailable(storeId,maxPrice,PageRequest.of(page,size,Sort.by("name").ascending())); return new PagedResponseDto<>(p.getContent().stream().map(x->new PublicProductResponseDto(x.getId(),stores.findById(x.getStoreId()).map(Store::getName).orElse(""),x.getName(),x.getPrice())).toList(),p.getNumber(),p.getSize(),p.getTotalElements());}
 private ProductResponseDto toResponse(Product p,Store s){return new ProductResponseDto(p.getId(),s.getName(),p.getName(),p.getPrice(),p.getStock(),p.getStatus());}
}
